// Install a Rust run-directory fixture (Q9 (e), generated by
// buckyos/src/frame/llm_context/tests/vectors/runs/generate.sh) under another
// root on this machine: every path under fixture.json `root` moves to the
// new root, `target.uid` becomes this machine's uid (the runtime id is
// derived from the target again, blake3 as Rust), and the mock endpoint may
// move to another port. The runtime's `host` stays `host:xllm-fixture:` —
// run with AGENT_TOOL_HOST_ID=xllm-fixture.
//
//   deno run --allow-read --allow-write --allow-run rewrite_paths.ts <fixture dir> <dest root> [--uid <uid>] [--base-url <url>]

import { blake3 } from '../../../../node_modules/@noble/hashes/blake3.js'
import { bytesToHex } from '../../../../node_modules/@noble/hashes/utils.js'

export interface FixtureInfo {
  root: string
  run_id: string
  uid: string
  host_id: string
  base_url: string
  api_key_env: string
}

export interface InstalledFixture {
  fixture: FixtureInfo
  root: string
  runsDir: string
  workdir: string
  runId: string
  runDir: string
}

export interface RewriteOptions {
  /** Default: this process's uid (`id -u`). */
  uid?: string
  /** The mock endpoint now serving the fixture's scenario. */
  baseUrl?: string
}

function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys)
  if (v && typeof v === 'object') {
    return Object.fromEntries(Object.keys(v as object).sort().map(k => [k, sortKeys((v as Record<string, unknown>)[k])]))
  }
  return v
}

/** `native:` + blake3 of the target's JSON (sorted keys, compact), first 24 hex. */
export function nativeRuntimeId(target: unknown): string {
  return `native:${bytesToHex(blake3(new TextEncoder().encode(JSON.stringify(sortKeys(target))))).slice(0, 24)}`
}

async function copyDir(from: string, to: string) {
  await Deno.mkdir(to, { recursive: true })
  for await (const e of Deno.readDir(from)) {
    const src = `${from}/${e.name}`
    const dst = `${to}/${e.name}`
    if (e.isDirectory) await copyDir(src, dst)
    else if (e.isFile) await Deno.copyFile(src, dst)
  }
}

async function textFiles(dir: string, out: string[] = []): Promise<string[]> {
  for await (const e of Deno.readDir(dir)) {
    const p = `${dir}/${e.name}`
    if (e.isDirectory) await textFiles(p, out)
    else if (e.isFile && (e.name.endsWith('.json') || e.name === '.llm_context')) out.push(p)
  }
  return out
}

async function currentUid(): Promise<string> {
  const out = await new Deno.Command('id', { args: ['-u'], stdout: 'piped' }).output()
  return new TextDecoder().decode(out.stdout).trim()
}

export async function installFixture(fixtureDir: string, destRoot: string, options: RewriteOptions = {}): Promise<InstalledFixture> {
  const fixture = JSON.parse(await Deno.readTextFile(`${fixtureDir}/fixture.json`)) as FixtureInfo
  await Deno.mkdir(destRoot, { recursive: true })
  const root = await Deno.realPath(destRoot)
  await copyDir(`${fixtureDir}/runs`, `${root}/runs`)
  await copyDir(`${fixtureDir}/work`, `${root}/work`)
  const uid = options.uid ?? await currentUid()
  const recordPath = `${root}/runs/${fixture.run_id}/run.json`
  const record = JSON.parse(await Deno.readTextFile(recordPath))
  const oldId: string = record.config.runtime_descriptor.runtime_id
  const target = { ...record.config.runtime_descriptor.target, uid }
  const newId = nativeRuntimeId(target)
  const replace = (text: string) => {
    let t = text.split(fixture.root).join(root)
    if (options.baseUrl) t = t.split(fixture.base_url).join(options.baseUrl)
    return t.split(oldId).join(newId)
  }
  for (const f of [...await textFiles(`${root}/runs`), ...await textFiles(`${root}/work`)]) {
    await Deno.writeTextFile(f, replace(await Deno.readTextFile(f)))
  }
  const rewritten = JSON.parse(await Deno.readTextFile(recordPath))
  rewritten.config.runtime_descriptor.target = target
  await Deno.writeTextFile(recordPath, JSON.stringify(rewritten, null, 2))
  return {
    fixture, root, runsDir: `${root}/runs`, workdir: `${root}/work`, runId: fixture.run_id, runDir: `${root}/runs/${fixture.run_id}`,
  }
}

if (import.meta.main) {
  const [fixtureDir, dest, ...rest] = Deno.args
  if (!fixtureDir || !dest) {
    console.error('usage: rewrite_paths.ts <fixture dir> <dest root> [--uid <uid>] [--base-url <url>]')
    Deno.exit(2)
  }
  const opt = (name: string) => {
    const i = rest.indexOf(`--${name}`)
    return i >= 0 ? rest[i + 1] : undefined
  }
  const installed = await installFixture(fixtureDir, dest, { uid: opt('uid'), baseUrl: opt('base-url') })
  console.log(JSON.stringify(installed, null, 2))
}
